void compactKeytips(){
 MainWindow window;window.resize(820,720);window.show();window.activateWindow();QApplication::processEvents();
 auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());auto* ribbon=window.findChild<QTabWidget*>("workspace.ribbon");
 const auto sheet=model->sheetId().toStdString();require(model->apply(Json::array({{{"type","set_cell"},{"sheet",sheet},{"row",7},{"col",3},{"input","0.125"},{"style",{{"numberFormat","0%"}}}}})),"prepare percentage precision shortcut");
 grid->setCurrentIndex(model->index(6,2));grid->selectionModel()->select(QItemSelection(model->index(6,2),model->index(6,4)),QItemSelectionModel::ClearAndSelect);window.executeCommand("view.ribbon");grid->setFocus();
 const auto before=window.currentSession().snapshot();const auto history=window.currentSession().historyBytes();const auto selection=grid->selectionModel()->selection();
 auto open=[&](Qt::Key tab){grid->setFocus();QTest::keyClick(grid,Qt::Key_Alt);QTest::keyClick(grid,tab);QApplication::processEvents();};
 auto visibleTips=[&](RibbonPage* page){
  const QRect viewport(page->viewport()->mapToGlobal(QPoint()),page->viewport()->size());QStringList keys;
  for(auto* tip:window.findChildren<QLabel*>())if(tip->objectName().startsWith("tutorial.keyTip.")&&tip->isVisible()){
   const QRect box(tip->mapToGlobal(QPoint()),tip->size());
   require(box.left()>=viewport.left()&&box.right()<=viewport.right(),"compact keytip must stay completely inside the ribbon viewport horizontally");keys<<tip->text();
  }
  for(auto* control:page->findChildren<QWidget*>()){
   const auto key=control->property("ribbon.keyTip").toString();if(key.isEmpty())continue;const QRect box(control->mapToGlobal(QPoint()),control->size());
   if(box.left()<viewport.left()||box.right()>viewport.right())require(!keys.contains(key),"partially clipped and offscreen controls must not display floating keytips");else if(control->isVisible()){require(keys.contains(key),"fully visible ribbon commands receive refreshed keytips");auto* tip=window.findChild<QLabel*>("tutorial.keyTip."+key);if(!tip||tip->mapToGlobal(QPoint()).y()!=control->mapToGlobal(QPoint(0,control->height()-4)).y())std::cerr<<"Detached keytip "<<key.toStdString()<<" control="<<control->objectName().toStdString()<<" tipY="<<(tip?tip->mapToGlobal(QPoint()).y():-999)<<" expectedY="<<control->mapToGlobal(QPoint(0,control->height()-4)).y()<<" width="<<window.width()<<" scroll="<<page->horizontalScrollBar()->value()<<"\n";require(tip&&tip->mapToGlobal(QPoint()).y()==control->mapToGlobal(QPoint(0,control->height()-4)).y(),"scrolling and resizing keep keytips attached to their command row");}
  }
  require(!keys.isEmpty(),"visible ribbon commands retain their keytips");return keys;
 };
 open(Qt::Key_H);auto* home=dynamic_cast<RibbonPage*>(ribbon->currentWidget());require(home&&home->hasOverflow(),"narrow Home has horizontally overflowing commands");
 const auto first=visibleTips(home);require(!first.contains("0"),"the initial narrow Home precision command is genuinely offscreen");
 home->horizontalScrollBar()->setValue(home->horizontalScrollBar()->maximum());QApplication::processEvents();const auto last=visibleTips(home);
 require(first!=last,"scrolling the command row refreshes badges for newly visible controls");
 home->horizontalScrollBar()->setValue(home->horizontalScrollBar()->minimum());QApplication::processEvents();require(!visibleTips(home).contains("0"),"scrolling back hides the offscreen precision badge again");
 require(window.currentSession().snapshot()==before&&window.currentSession().historyBytes()==history&&grid->selectionModel()->selection()==selection,"keytip display and scrolling preserve selection, cells and history");
 QTest::keyClick(grid,Qt::Key_0);QApplication::processEvents();require(model->cellStyle(6,2).value("numberFormat",std::string())=="0.0%"&&grid->selectionModel()->selection()==selection,"offscreen Alt H0 remains a real precision command for the selected range");
 require(window.executeCommand("undo")&&window.currentSession().snapshot().at("sheets")==before.at("sheets"),"one Undo reverses only the actual precision edit");
 open(Qt::Key_W);auto* view=dynamic_cast<RibbonPage*>(ribbon->currentWidget());visibleTips(view);view->horizontalScrollBar()->setValue(view->horizontalScrollBar()->maximum());QApplication::processEvents();visibleTips(view);QTest::keyClick(grid,Qt::Key_Escape);
 open(Qt::Key_H);home->horizontalScrollBar()->setValue(0);QApplication::processEvents();const auto resizeBefore=window.currentSession().snapshot();const auto resizeHistory=window.currentSession().historyBytes();
 window.resize(1410,720);QApplication::processEvents();QApplication::processEvents();auto* stack=ribbon->findChild<QStackedWidget*>();
 require(stack&&stack->width()==ribbon->width(),"an open collapsed ribbon popup follows the resized window width");visibleTips(home);
 require(window.currentSession().snapshot()==resizeBefore&&window.currentSession().historyBytes()==resizeHistory&&grid->selectionModel()->selection()==selection,"resizing an open keytip ribbon preserves worksheet state");QTest::keyClick(grid,Qt::Key_Escape);
}
