 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());const auto sheet=model->sheetId().toStdString();require(model->apply(Json::array({{{"type","set_cell"},{"sheet",sheet},{"row",1},{"col",1},{"input","43830"},{"style",{{"numberFormat","m/d/yyyy"},{"bold",true},{"fill","#d9d9d9"}}}},{{"type","set_cell"},{"sheet",sheet},{"row",1},{"col",2},{"input","=1+2"}}})),"seed a formatted source and formula destination");grid->setCurrentIndex(model->index(0,0));require(window.executeCommand("copy"),"copy the formatted source");grid->setCurrentIndex(model->index(0,1));bool formatsRadio=false;QTimer::singleShot(0,[&]{auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());if(!dialog)return;for(auto* radio:dialog->findChildren<QRadioButton*>())if(QString(radio->text()).remove('&')=="Formats")formatsRadio=true;if(!formatsRadio){dialog->reject();return;}QTest::keyClick(dialog,Qt::Key_T);QTest::keyClick(dialog,Qt::Key_Return);});require(window.executeCommand("paste.special")&&formatsRadio,"Paste Special exposes Formats as a native radio option selected by T and accepted with Enter");const auto style=model->cellStyle(0,1);require(model->raw(0,1)=="=1+2"&&style.at("numberFormat")=="m/d/yyyy"&&style.at("bold")==true&&style.at("fill")=="#d9d9d9","Formats radio pastes only formatting and retains the destination formula");require(window.executeCommand("undo")&&model->raw(0,1)=="=1+2"&&!model->cellStyle(0,1).contains("fill"),"the actual Paste Special dialog produces one undoable format edit");
