void missingParenthesisWarning(){
 for(bool inCell:{false,true}){
  MainWindow window;window.show();window.activateWindow();QApplication::processEvents();auto* grid=window.findChild<WorksheetView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());grid->setCurrentIndex(model->index(26,3));grid->setFocus();QLineEdit* editor=window.findChild<QLineEdit*>("formula.input");if(inCell){QTest::keyClick(grid,Qt::Key_F2);editor=grid->activeCellEditor();}require(editor,"a native editor is available");editor->setFocus();editor->selectAll();QTest::keyClicks(editor,"=-D69/SUM(D40:D41");const auto before=window.currentSession().snapshot();const int cursor=editor->cursorPosition();int dialogs=0;bool correction=false,warning=false,timedOut=false;QPointer<QMessageBox> previousDialog;
  QTimer responder,watchdog,cleanup;responder.setInterval(1);watchdog.setSingleShot(true);cleanup.setInterval(10);
  QObject::connect(&cleanup,&QTimer::timeout,&window,[]{if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->reject();});
  QObject::connect(&watchdog,&QTimer::timeout,&window,[&]{timedOut=true;responder.stop();cleanup.start();if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->reject();});
  QObject::connect(&responder,&QTimer::timeout,&window,[&]{auto* dialog=qobject_cast<QMessageBox*>(QApplication::activeModalWidget());if(!dialog||dialog==previousDialog)return;previousDialog=dialog;++dialogs;
   if(dialogs==1){correction=dialog->objectName()=="worksheet.formulaCorrection"&&dialog->icon()==QMessageBox::Information&&dialog->standardButtons()==(QMessageBox::Yes|QMessageBox::No)&&dialog->text().contains("=-D69/SUM(D40:D41)")&&window.currentSession().snapshot()==before;if(auto* no=dialog->button(QMessageBox::No))QTest::mouseClick(no,Qt::LeftButton);else dialog->reject();}
   else if(dialogs==2){warning=dialog->text()=="The formula is missing an opening or closing parenthesis."&&dialog->icon()==QMessageBox::Warning&&dialog->standardButtons()==QMessageBox::Ok&&window.currentSession().snapshot()==before;if(auto* okay=dialog->button(QMessageBox::Ok))QTest::mouseClick(okay,Qt::LeftButton);else dialog->reject();}
   else dialog->reject();
  });
  responder.start();watchdog.start(3000);QTest::keyClick(editor,Qt::Key_Return);responder.stop();watchdog.stop();cleanup.stop();QApplication::processEvents();require(!timedOut&&dialogs==2&&correction&&warning,"a missing function close offers the Information Yes/No correction, then rejecting it displays the distinct Warning/OK dialog");require(window.currentSession().snapshot()==before&&grid->currentIndex()==model->index(26,3)&&editor->text()=="=-D69/SUM(D40:D41"&&editor->cursorPosition()==cursor&&editor->hasFocus(),"dismissing both dialogs retains the draft, caret, active cell and history for correction");editor->selectAll();QTest::keyClicks(editor,"=-D69/SUM(D40:D42)");QTest::keyClick(editor,Qt::Key_Return);require(model->raw(26,3)=="=-D69/SUM(D40:D42)"&&grid->currentIndex()==model->index(27,3)&&window.currentSession().snapshotView().at("revision").get<int>()==before.at("revision").get<int>()+1,"correcting the range and parenthesis commits and advances exactly once");require(window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"the later corrected formula is one undoable edit");
  grid->setCurrentIndex(model->index(28,3));editor=window.findChild<QLineEdit*>("formula.input");editor->setFocus();editor->selectAll();QTest::keyClicks(editor,"=\"(\"");QTest::keyClick(editor,Qt::Key_Return);require(model->raw(28,3)=="=\"(\"","a parenthesis inside a quoted string is not a syntax warning");
 }
}
